message:
Command `cd /workspace && bash build.sh 'cat > /gt/libicalvcard_fuzzer.c <<"EOF"
#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include "libicalvcard/vcardparser.h"
#include "libicalvcard/vcardcomponent.h"
int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size) {
    char *str = (char *)malloc(Size + 1);
    if (!str) return 0;
    memcpy(str, Data, Size);
    str[Size] = 0;
    vcardcomponent *card = vcardparser_parse_string(str);
    if (card) {
        char *out = vcardcomponent_as_vcard_string_r(card);
        if (out) free(out);
        vcardcomponent *clone = vcardcomponent_clone(card);
        if (clone) vcardcomponent_free(clone);
        vcardcomponent_free(card);
    }
    free(str);
    return 0;
}
EOF
clang -fsanitize=fuzzer,memory -fsanitize-memory-track-origins=2 -O1 -g -fPIE -fno-omit-frame-pointer -I/gt/build-msan-static/src -I/gt/build-msan-static/src/libical -I/gt/build-msan-static/src/libicalvcard -I/gt/_work/src/src -I/gt/_work/src/src/libical -I/gt/_work/src/src/libicalvcard /gt/libicalvcard_fuzzer.c -o /gt/libicalvcard_fuzzer /gt/build-msan-static/lib/libicalvcard.a /gt/build-msan-static/lib/libical.a -licui18n -licuuc -licudata -lm -lpthread
/gt/libicalvcard_fuzzer /gt/poc1.vcf -runs=1 >/tmp/out 2>&1; echo exit:$?; grep -n "MemorySanitizer\|WARNING\|vcardstructured\|vcardparameter_free" /tmp/out | head -120'` executed with exit code -1.

